  Notation SAk k SE pc mm x1 x7 x8 x9 a0 a1 a2 a3 x18 x19 x20 x21 x22 x23 x24 x26 x27 x29 x31 :=
    (MS (mkR x1 (Z_to_bv 64 SPF) gp tp (Z_to_bv 64 (SP + -256)) (Z_to_bv 64 4) x7 x8 x9 a0 a1 a2 a3
             (Z_to_bv 64 (SP + -136)) (Z_to_bv 64 k) (Z_to_bv 64 AW4_DBC) (Z_to_bv 64 seg)
             x18 x19 x20 x21 x22 x23 x24 (Z_to_bv 64 64) x26 x27 (Z_to_bv 64 0x20dc4) x29 (Z_to_bv 64 SE) x31)
        FR (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).

  Lemma w4f_step : forall k prev mm w88 w96 w112 w120 w128 w224 w232 ws
                          (x1 x7 x8 x9 x11 x12 x13 x18 x19 x20 x21 x22 x23 x24 x26 x27 x29 x30 x31 : word),
    0 <= k < 4 -> W4M mm w88 w96 (Z_to_bv 64 0xff34) w112 w120 w128 w224 w232 ws -> nth_error ws 13 = Some (Z_to_bv 64 SS) ->
    WSOK ws k -> DST <= prev <= DST + dcap ->
    (forall SE mm' ws' (x1' x7' x8' x9' a0' a1' a2' a3' x18' x19' x20' x21' x22' x23' x24' x26' x27' x29' x31' : word),
       W4M mm' w88 w96 (Z_to_bv 64 0xff34) w112 w120 w128 w224 w232 ws' -> nth_error ws' 13 = Some (Z_to_bv 64 SS) ->
       WSOK ws' (k + 1) -> DST <= SE <= DST + dcap ->
       evtF asegs RNG POST (SAk k SE 0x900a0 mm' x1' x7' x8' x9' a0' a1' a2' a3' x18' x19' x20' x21' x22' x23' x24' x26' x27' x29' x31')) ->
    evtF asegs RNG POST (KH 0x8fab0 mm k prev x1 x7 x8 x9 x11 x12 x13 x18 x19 x20 x21 x22 x23 x24 x26 x27 x29 x30 x31).
